/**
 * The leader's clocks and starters, classified (switch-stop-writers-ratchet.test.ts "the leader's clocks, from the source").
 *
 * CLOCKS: every file under src/ with a periodic timer (clock-scan.ts: a `setInterval(` or a `runPeriodic(`), one entry
 * per timer in source order ('same': as the one before). STARTERS: every module web/server.ts starts with a `start*`
 * function (a `void import(...).then(m => m.startX())` or a `const { startX } = await import(...)`) that has no such
 * timer of its own: a self re-arming setTimeout, a bus subscription, a helper's timer. Kinds:
 *  - gated: its tick or handler asks homeWritesStopped() (src/lib/leader-clocks.ts) first, so it writes nothing
 *    once a leader switch's stop began;
 *  - stopped: stopServer stops it before the final batch (the text is its call there); a tick already past its check
 *    may land one write, which the final batch's next pass carries;
 *  - helper (STARTERS only): its timer is another file's, classified in CLOCKS;
 *  - once (STARTERS only): writes leader data at most once a boot or once an edge;
 *  - none: writes no leader data (memory, the network, machine-local or rebuildable places);
 *  - not-server: not run by a leader's server (a CLI command, a test server, a fixture).
 * Read from the source on 2026-11-25 (an audit of each timer, its writes and where they land in the home manifest).
 */
export type ClockKind = 'gated' | 'stopped' | 'none' | 'not-server'
/** [kind, what it writes and why that kind, its stop call in stopServer (stopped only)], or 'same'. */
export type Clock = [ClockKind, string, string?] | 'same'
